use crate::ast::obj::{Literal, Obj};
use crate::rational_expression::exact_rational::evaluate_obj_to_exact_rational_obj_for_eval;
use crate::rational_expression::evaluate_obj_to_normalized_decimal_number;
use crate::rational_expression::ClosedNumericExpr;

// Residual must already classify as ClosedNumericExpr.
// Prefer exact rational (keeps fractions); else normalized decimal Number.
// Simple: `1/2` → `1/2`; `abs(-3)` → `3`.
// Complex nested: examples/.../eval_closed_numeric_complex.lit
//   e.g. `eval gcd(54, (-24)) + 3! * sqrt(4)`, `eval a + b * c` after closed `have`.
pub fn evaluate_closed_numeric_obj(obj: &Obj) -> Option<Obj> {
    if ClosedNumericExpr::try_from_obj(obj).is_none() {
        return None;
    }
    if let Some(exact) = evaluate_obj_to_exact_rational_obj_for_eval(obj) {
        return Some(exact);
    }
    evaluate_obj_to_normalized_decimal_number(obj).map(|number| Obj::Literal(Literal::Number(number)))
}

initial_readonly_source_snapshots.src/execute/execute_eval_stmt/evaluate_o:
use super::dispatch_algo::evaluate_fn_obj_with_algo;
use super::evaluate_closed_numeric::evaluate_closed_numeric_obj;
use super::helper::{ActiveAlgoCalls, MAX_EVAL_DEPTH};
use super::result::ExecEvalStmtFailed;
use crate::ast::obj::{
    Abs, Add, ArithmeticOperator, Ceil, Div, Floor, Max, Min, Mul, Neg, Obj, Pow, Sign, Sub,
};
use crate::rational_expression::ClosedNumericExpr;
use crate::runtime::{Runtime, RuntimeResult};

// Recursive display evaluation after closed-numeric equal rewrite.
//
// Supported residual shapes:
// - ClosedNumericExpr → exact/decimal simplify
// - ArithmeticOperator whose children evaluate → rebuild → simplify
// - FnObj with plain Identifier head + stored algo → dispatch → recurse
//
// Example: `nonzero_flag(0) + 1` → `0 + 1` → `1`
pub fn evaluate_obj(
    runtime: &mut Runtime,
    obj: &Obj,
    depth: usize,
    active_calls: &mut ActiveAlgoCalls,
) -> RuntimeResult<Result<Obj, ExecEvalStmtFailed>> {
    if depth > MAX_EVAL_DEPTH {
        return Ok(Err(ExecEvalStmtFailed::DepthExceeded));
    }

    if ClosedNumericExpr::try_from_obj(obj).is_some() {
        return Ok(match evaluate_closed_numeric_obj(obj) {
            Some(v) => Ok(v),
            None => Err(ExecEvalStmtFailed::EvaluationFailed),
        });
    }

    match obj {
        Obj::ComplexOperator(_) => Ok(match crate::rational_expression::exact_complex::exact_modulus_value(obj) {
            Some(value) => Ok(value), None => Err(ExecEvalStmtFailed::UnsupportedExpression),
        }),
        Obj::FiniteSetStat(_) | Obj::ProductShape(_) => super::evaluate_finite_objects::evaluate_finite_object(runtime,obj,depth,active_calls),
        Obj::ArithmeticOperator(op) => {
            evaluate_arithmetic_operator(runtime, op, depth, active_calls)
        }
        Obj::IteratedOperator(op) => {
            super::evaluate_aggregate::evaluate_aggregate(runtime, op, depth, active_calls)
        }
        Obj::FnObj(fn_obj) => {
            if let Some(expansion) =
                runtime.expanded_named_or_literal_anon_fn_application_body(fn_obj)?
            {
                let application_well_defined = match runtime.verify_obj_well_definedness(
                    obj,
                    crate::execute::execute_by_stmt::proof_verify_state()
                        ,
                )? {
                    crate::execute::execute_fact_stmt::VerifyObjWellDefinedResult::Success(p) => p,
                    failed => return Ok(Err(ExecEvalStmtFailed::WellDefined(Box::new(failed)))),
                };
                let (body, cites) =
                    runtime.rewrite_obj_by_known_closed_numeric_equal(&expansion.expanded_body);
                active_calls.cited_equal_fact_ids.extend(cites);
                let value = match evaluate_obj(runtime, &body, depth + 1, active_calls)? {
                    Ok(v) => v,
                    Err(e) => return Ok(Err(e)),
                };
                active_calls.function_evaluations.push(
                    super::aggregate_evaluation_result::FunctionApplicationEvaluationResult {
                        application: obj.clone(),
                        application_well_defined,
                        expansion,
                        value: value.clone(),
                    },
                );
                Ok(Ok(value))
            } else {
                evaluate_fn_obj_with_algo(runtime, fn_obj, depth, active_calls)
            }
        }
        _ => Ok(Err(ExecEvalStmtFailed::UnsupportedExpression)),
    }
}

fn evaluate_arithmetic_operator(
    runtime: &mut Runtime,
    op: &ArithmeticOperator,
    depth: usize,
    active_calls: &mut ActiveAlgoCalls,
) -> RuntimeResult<Result<Obj, ExecEvalStmtFailed>> {
    match op {
        ArithmeticOperator::Add(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Add(Add {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Sub(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Sub(Sub {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Mul(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Mul(Mul {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Div(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Div(Div {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Min(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Min(Min {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Max(a) => {
            eval_bin(runtime, &a.left, &a.right, depth, active_calls, |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Max(Max {
                    left: Box::new(l),
                    right: Box::new(r),
                }))
            })
        }
        ArithmeticOperator::Pow(a) => eval_bin(
            runtime,
            &a.base,
            &a.exponent,
            depth,
            active_calls,
            |l, r| {
                Obj::ArithmeticOperator(ArithmeticOperator::Pow(Pow {
                    base: Box::new(l),
                    exponent: Box::new(r),
                }))
            },
        ),
        ArithmeticOperator::Neg(a) => eval_un(runtime, &a.arg, depth, active_calls, |arg| {
            Obj::ArithmeticOperator(ArithmeticOperator::Neg(Neg { arg: Box::new(arg) }))
        }),
        ArithmeticOperator::Abs(a) => eval_un(runtime, &a.arg, depth, active_calls, |arg| {
            Obj::ArithmeticOperator(ArithmeticOperator::Abs(Abs { arg: Box::new(arg) }))
        }),
        ArithmeticOperator::Floor(a) => eval_un(runtime, &a.arg, depth, active_calls, |arg| {
            Obj::ArithmeticOperator(ArithmeticOperator::Floor(Floor { arg: Box::new(arg) }))
        }),
        ArithmeticOperator::Ceil(a) => eval_un(runtime, &a.arg, depth, active_calls, |arg| {
            Obj::ArithmeticOperator(ArithmeticOperator::Ceil(Ceil { arg: Box::new(arg) }))
        }),
        ArithmeticOperator::Sign(a) => eval_un(runtime, &a.arg, depth, active_calls, |arg| {
            Obj::ArithmeticOperator(ArithmeticOperator::Sign(Sign { arg: Box::new(arg) }))
        }),
    }
}

fn eval_bin<F>(
    runtime: &mut Runtime,
    left: &Obj,
    right: &Obj,
    depth: usize,
    active_calls: &mut ActiveAlgoCalls,
    rebuild: F,
) -> RuntimeResult<Result<Obj, ExecEvalStmtFailed>>
where
    F: FnOnce(Obj, Obj) -> Obj,
{
    let left_v = match evaluate_obj(runtime, left, depth + 1, active_calls)? {
        Ok(v) => v,
        Err(failed) => return Ok(Err(failed)),
    };
    let right_v = match evaluate_obj(runtime, right, depth + 1, active_calls)? {
        Ok(v) => v,
        Err(failed) => return Ok(Err(failed)),
    };
    let combined = rebuild(left_v, right_v);
    Ok(match evaluate_closed_numeric_obj(&combined) {
        Some(v) => Ok(v),
        None => Err(ExecEvalStmtFailed::EvaluationFailed),
    })
}

fn eval_un<F>(
    runtime: &mut Runtime,
    arg: &Obj,
    depth: usize,
    active_calls: &mut ActiveAlgoCalls,
    rebuild: F,
) -> RuntimeResult<Result<Obj, ExecEvalStmtFailed>>
where
    F: FnOnce(Obj) -> Obj,
{
    let arg_v = match evaluate_obj(runtime, arg, depth + 1, active_calls)? {
        Ok(v) => v,
        Err(failed) => return Ok(Err(failed)),
    };
    let combined = rebuild(arg_v);
    Ok(match evaluate_closed_numeric_obj(&combined) {
        Some(v) => Ok(v),
        None => Err(ExecEvalStmtFailed::EvaluationFailed),
    })
}

initial_readonly_source_snapshots.src/execute/execute_fact_stmt/verify_ato:
use crate::ast::obj::StandardSet;
use crate::rational_expression::exact_rational::EvalRational;
use crate::rational_expression::NumberCompareResult;

// Success evidence only. Unsupported expressions and false goals yield None at
// the calculator boundary, never a successful proof with a failure flag.
pub enum ClosedCalculationProof {
    Equality(ClosedEqualityCalculationProof),
    AtomicExceptEquality(ClosedAtomicExceptEqualityCalculationProof),
}

pub struct ClosedEqualityCalculationProof {
    pub values: ClosedValuePair,
}

pub enum ClosedAtomicExceptEqualityCalculationProof {
    NotEqual(ClosedNotEqualCalculationProof),
    Less(ClosedComparisonCalculationProof),
    Greater(ClosedComparisonCalculationProof),
    LessEqual(ClosedComparisonCalculationProof),
    GreaterEqual(ClosedComparisonCalculationProof),
    NotLess(ClosedComparisonCalculationProof),
    NotGreater(ClosedComparisonCalculationProof),
    NotLessEqual(ClosedComparisonCalculationProof),
    NotGreaterEqual(ClosedComparisonCalculationProof),
    In(ClosedMembershipCalculationProof),
    NotIn(ClosedMembershipCalculationProof),
}

// Both values use the same exact representation. Decimal strings are normalized;
// rational/complex arithmetic uses checked exact fractions, never floats.
pub enum ClosedValuePair {
    Decimal { left: String, right: String },
    Rational { left: EvalRational, right: EvalRational },
    Complex {
        left_real: EvalRational,
        left_imaginary: EvalRational,
        right_real: EvalRational,
        right_imaginary: EvalRational,
    },
}

pub struct ClosedNotEqualCalculationProof {
    pub values: ClosedValuePair,
}

pub struct ClosedComparisonCalculationProof {
    pub left_normal: String,
    pub right_normal: String,
    pub comparison: NumberCompareResult,
}

pub enum ClosedScalarValue {
    Decimal(String),
    ExactComplex { real: EvalRational, imaginary: EvalRational },
}

pub struct ClosedMembershipCalculationProof {
    pub value: ClosedScalarValue,
    pub set: StandardSet,
}

use super::closed_calculation_proof::*;
use crate::ast::fact::AtomicFact;
use crate::ast::obj::{Obj, StandardSet};
use crate::rational_expression::closed_scalar_membership::{
    exact_complex_inhabits_standard_set, normalized_decimal_inhabits_standard_set,
};
use crate::rational_expression::exact_complex::exact_complex_coordinates;
use crate::rational_expression::exact_rational::EvalRational;
use crate::rational_expression::{
    compare_closed_numeric_objs, evaluate_obj_to_normalized_decimal_number,
    NumberCompareResult,
};

// This leaf has no Runtime, VerifyState or search callback. It only evaluates
// finite closed ASTs. False, unsupported, undefined and overflowing calculations
// return no certificate. WD remains mandatory at the outer verify boundary.
pub fn calculate_closed_atomic_fact(fact: &AtomicFact) -> Option<ClosedCalculationProof> {
    use AtomicFact::*;
    use ClosedAtomicExceptEqualityCalculationProof as P;
    use NumberCompareResult::{Equal, Greater, Less};

    let proof = match fact {
        EqualFact(f) => {
            let (values, equal) = calculate_value_pair(&f.left, &f.right)?;
            return equal.then_some(ClosedCalculationProof::Equality(
                ClosedEqualityCalculationProof { values },
            ));
        }
        NotEqualFact(f) => {
            let (values, equal) = calculate_value_pair(&f.left, &f.right)?;
            if equal { return None; }
            P::NotEqual(ClosedNotEqualCalculationProof { values })
        }
        LessFact(f) => P::Less(calculate_comparison(&f.left, &f.right, &[Less])?),
        GreaterFact(f) => P::Greater(calculate_comparison(&f.left, &f.right, &[Greater])?),
        LessEqualFact(f) => P::LessEqual(calculate_comparison(&f.left, &f.right, &[Less, Equal])?),
        GreaterEqualFact(f) => P::GreaterEqual(calculate_comparison(&f.left, &f.right, &[Greater, Equal])?),
        NotLessFact(f) => P::NotLess(calculate_comparison(&f.left, &f.right, &[Greater, Equal])?),
        NotGreaterFact(f) => P::NotGreater(calculate_comparison(&f.left, &f.right, &[Less, Equal])?),
        NotLessEqualFact(f) => P::NotLessEqual(calculate_comparison(&f.left, &f.right, &[Greater])?),
        NotGreaterEqualFact(f) => P::NotGreaterEqual(calculate_comparison(&f.left, &f.right, &[Less])?),
        InFact(f) => P::In(calculate_membership(&f.element, &f.set, true)?),
        NotInFact(f) => P::NotIn(calculate_membership(&f.element, &f.set, false)?),
        // Explicitly unsupported families: calculation does not unfold a
        // predicate or generate structural/set-theoretic proof obligations.
        NormalAtomicFact(_) | NotNormalAtomicFact(_)
        | IsSetFact(_) | NotIsSetFact(_)
        | IsNonemptySetFact(_) | NotIsNonemptySetFact(_)
        | IsFiniteSetFact(_) | NotIsFiniteSetFact(_)
        | IsCartFact(_) | NotIsCartFact(_)
        | IsTupleFact(_) | NotIsTupleFact(_)
        | SubsetFact(_) | NotSubsetFact(_)
        | SupersetFact(_) | NotSupersetFact(_)
        | ProperSubsetFact(_) | NotProperSubsetFact(_)
        | ProperSupersetFact(_) | NotProperSupersetFact(_)
        | PrimeFact(_) | NotPrimeFact(_)
        | CoprimeFact(_) | NotCoprimeFact(_)
        | DvdFact(_) | NotDvdFact(_)
        | InjectiveFact(_) | NotInjectiveFact(_)
        | SurjectiveFact(_) | NotSurjectiveFact(_)
        | BijectiveFact(_) | NotBijectiveFact(_)
        | IsChoiceFunctionForFact(_) | NotIsChoiceFunctionForFact(_) => return None,
    };
    Some(ClosedCalculationProof::AtomicExceptEquality(proof))
}

// Preserve the existing decimal leaf, then exact fractions and complex
// coordinates. Symbolic monomial normalization deliberately stays in Builtin.
fn calculate_value_pair(left: &Obj, right: &Obj) -> Option<(ClosedValuePair, bool)> {
    if let (Some(left), Some(right)) = (
        evaluate_obj_to_normalized_decimal_number(left),
        evaluate_obj_to_normalized_decimal_number(right),
    ) {
        let equal = left.normalized_value == right.normalized_value;
        return Some((ClosedValuePair::Decimal {
            left: left.normalized_value, right: right.normalized_value,
        }, equal));
    }
    if let (Some(left), Some(right)) = (EvalRational::from_obj(left), EvalRational::from_obj(right)) {
        let equal = left == right;
        return Some((ClosedValuePair::Rational { left, right }, equal));
    }
    let (left_real, left_imaginary) = exact_complex_coordinates(left)?;
    let (right_real, right_imaginary) = exact_complex_coordinates(right)?;
    let equal = left_real == right_real && left_imaginary == right_imaginary;
    Some((ClosedValuePair::Complex { left_real, left_imaginary, right_real, right_imaginary }, equal))
}

fn calculate_comparison(
    left: &Obj, right: &Obj, accepted: &[NumberCompareResult],
) -> Option<ClosedComparisonCalculationProof> {
    let (comparison, left_normal, right_normal) = compare_closed_numeric_objs(left, right)?;
    if !accepted.contains(&comparison) { return None; }
    Some(ClosedComparisonCalculationProof { left_normal, right_normal, comparison })
}

fn calculate_membership(element: &Obj, set: &Obj, positive: bool) -> Option<ClosedMembershipCalculationProof> {
    let Obj::StandardSet(set) = set else { return None; };
    let (value, admitted) = calculate_scalar_membership(element, set)?;
    if admitted != positive { return None; }
    Some(ClosedMembershipCalculationProof { value, set: set.clone() })
}

fn calculate_scalar_membership(element: &Obj, set: &StandardSet) -> Option<(ClosedScalarValue, bool)> {
    if let Some(number) = evaluate_obj_to_normalized_decimal_number(element) {
        let admitted = normalized_decimal_inhabits_standard_set(&number.normalized_value, set);
        return Some((ClosedScalarValue::Decimal(number.normalized_value), admitted));
    }
    let (real, imaginary) = exact_complex_coordinates(element)?;
    let admitted = exact_complex_inhabits_standard_set(&real, &imaginary, set);
    Some((ClosedScalarValue::ExactComplex { real, imaginary }, admitted))
}

